+	assert.NotContains(t, err.Error(), secret)
+	assert.NotContains(t, err.Error(), "private")
+	message := redactConnectionError(fmt.Errorf("failed %s password=%s", raw, secret), raw, "")
+	assert.False(t, strings.Contains(message, secret))
